import{_ as e,o as r,c as i,a6 as t}from"./chunks/framework.BBIckNDn.js";const c=JSON.parse('{"title":"リアルタイムグラフィックス完全Wiki","description":"","frontmatter":{"title":"リアルタイムグラフィックス完全Wiki","study":{"source":"RenderingWiki","kind":"索引","status":"既存原稿","summary":"GPUとレンダリングを一つの知識体系として学ぶ ゲームプログラマのための「一生物の教材」。GPUの仕組みから Unity / Unreal / DirectX12 / Vulkan、そして最先端のGI・アップスケーリングまで。"}},"headers":[],"relativePath":"graphics/rendering-intro.md","filePath":"graphics/rendering-intro.md"}'),h={name:"graphics/rendering-intro.md"};function n(p,a,d,l,o,s){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="リアルタイムグラフィックス完全wiki" tabindex="-1">リアルタイムグラフィックス完全Wiki <a class="header-anchor" href="#リアルタイムグラフィックス完全wiki" aria-label="Permalink to &quot;リアルタイムグラフィックス完全Wiki&quot;">​</a></h1><p>GPUとレンダリングを一つの知識体系として学ぶ</p><p>ゲームプログラマのための「一生物の教材」。GPUの仕組みから Unity / Unreal / DirectX12 / Vulkan、そして最先端のGI・アップスケーリングまで。</p><ul><li><a href="/study/guide/rendering/roadmap.html">学習を始める</a></li><li><a href="/study/guide/rendering/about.html">このWikiについて</a></li><li><a href="/study/guide/rendering/timeline.html">技術全史年表</a></li></ul><h2 id="gpu基礎" tabindex="-1">GPU基礎 <a class="header-anchor" href="#gpu基礎" aria-label="Permalink to &quot;GPU基礎&quot;">​</a></h2><p>GPUとは何か、CPUとの役割分担、SIMTアーキテクチャ、メモリ階層。すべての土台となるハードウェアの理解。</p><p><a href="/study/hardware/gpu/what-is-gpu.html">この項目を読む</a></p><h2 id="_3d数学" tabindex="-1">3D数学 <a class="header-anchor" href="#_3d数学" aria-label="Permalink to &quot;3D数学&quot;">​</a></h2><p>ベクトル・行列・座標変換・カメラ・クォータニオン。レンダリングを支える数学を「なぜ」から理解する。</p><p><a href="/study/math/rendering/vector.html">この項目を読む</a></p><h2 id="レンダリングパイプライン" tabindex="-1">レンダリングパイプライン <a class="header-anchor" href="#レンダリングパイプライン" aria-label="Permalink to &quot;レンダリングパイプライン&quot;">​</a></h2><p>Vertex Shader から Fragment Shader、そして Mesh Shader まで。頂点がピクセルになるまでの全工程。</p><p><a href="/study/graphics/pipeline/overview.html">この項目を読む</a></p><h2 id="シェーダ言語" tabindex="-1">シェーダ言語 <a class="header-anchor" href="#シェーダ言語" aria-label="Permalink to &quot;シェーダ言語&quot;">​</a></h2><p>HLSL / GLSL / WGSL / MSL / SPIR-V。言語間の対応関係とコンパイルパイプラインを横断的に比較。</p><p><a href="/study/graphics/shader/overview.html">この項目を読む</a></p><h2 id="グラフィックスapi" tabindex="-1">グラフィックスAPI <a class="header-anchor" href="#グラフィックスapi" aria-label="Permalink to &quot;グラフィックスAPI&quot;">​</a></h2><p>OpenGL から DirectX12・Vulkan・Metal・WebGPU へ。APIの進化の歴史と、明示的APIの設計思想。</p><p><a href="/study/graphics/api/history.html">この項目を読む</a></p><h2 id="gpuコンピューティング" tabindex="-1">GPUコンピューティング <a class="header-anchor" href="#gpuコンピューティング" aria-label="Permalink to &quot;GPUコンピューティング&quot;">​</a></h2><p>Compute Shader、Warp/Wave、Shared Memory、Reduction、Prefix Sum。GPUを汎用計算機として使いこなす。</p><p><a href="/study/graphics/compute/compute-shader.html">この項目を読む</a></p><h2 id="ライティングとgi" tabindex="-1">ライティングとGI <a class="header-anchor" href="#ライティングとgi" aria-label="Permalink to &quot;ライティングとGI&quot;">​</a></h2><p>PBR・IBL・シャドウ・SSAO・SSR・レイトレーシング・Lumen。光の物理と近似手法の系譜。</p><p><a href="/study/graphics/lighting/pbr.html">この項目を読む</a></p><h2 id="ポストプロセスとaa" tabindex="-1">ポストプロセスとAA <a class="header-anchor" href="#ポストプロセスとaa" aria-label="Permalink to &quot;ポストプロセスとAA&quot;">​</a></h2><p>TAA・FXAA・DLSS・FSR・XeSS。現代のゲームグラフィックスを支える画像処理技術。</p><p><a href="/study/graphics/postprocess/overview.html">この項目を読む</a></p><h2 id="gpu最適化" tabindex="-1">GPU最適化 <a class="header-anchor" href="#gpu最適化" aria-label="Permalink to &quot;GPU最適化&quot;">​</a></h2><p>RenderGraph、GPU Driven Rendering、RenderDoc / PIX / Nsight によるプロファイリング。</p><p><a href="/study/graphics/optimization/basics.html">この項目を読む</a></p><h2 id="エンジンのレンダラー" tabindex="-1">エンジンのレンダラー <a class="header-anchor" href="#エンジンのレンダラー" aria-label="Permalink to &quot;エンジンのレンダラー&quot;">​</a></h2><p>Unity SRP / URP / HDRP、Unreal Engine のレンダラー。商用エンジンの内部実装を理解する。</p><p><a href="/study/graphics/engine/unity-renderer.html">この項目を読む</a></p><h2 id="ゼロからレンダラーを作る" tabindex="-1">ゼロからレンダラーを作る <a class="header-anchor" href="#ゼロからレンダラーを作る" aria-label="Permalink to &quot;ゼロからレンダラーを作る&quot;">​</a></h2><p>最終章。CPUからGPUまで、1フレームが描画されるまでを実装を通して総まとめ。</p><p><a href="/study/graphics/capstone/01-design.html">この項目を読む</a></p><h2 id="学習ロードマップ" tabindex="-1">学習ロードマップ <a class="header-anchor" href="#学習ロードマップ" aria-label="Permalink to &quot;学習ロードマップ&quot;">​</a></h2><p>どこから読めばいいか迷ったらここ。知識ツリーに沿った推奨学習順序を提示。</p><p><a href="/study/guide/rendering/roadmap.html">この項目を読む</a></p>',40)])])}const m=e(h,[["render",n]]);export{c as __pageData,m as default};
